function validate([wordlist, queries]) {
  if (!Array.isArray(wordlist) || wordlist.length < 1 || wordlist.length > 5000) return 'wordlist needs 1 to 5000 words.';
  if (!Array.isArray(queries) || queries.length < 1 || queries.length > 5000) return 'queries needs 1 to 5000 words.';
  for (const word of [...wordlist, ...queries]) {
    if (typeof word !== 'string' || word.length < 1 || word.length > 7) return 'Every word has 1 to 7 letters.';
    if (!/^[A-Za-z]+$/.test(word)) return 'Words use English letters only.';
  }
  return null;
}

