function spellchecker(wordlist, queries) {
  const exact = new Set(wordlist);
  const byLower = new Map();
  const byPattern = new Map();
  const pattern = (word) => word.toLowerCase().replace(/[aeiou]/g, '*');

  for (const word of wordlist) {
    const lower = word.toLowerCase();
    if (!byLower.has(lower)) {
      byLower.set(lower, word);
    }
    const key = pattern(word);
    if (!byPattern.has(key)) {
      byPattern.set(key, word);
    }
  }

  const answer = [];
  for (const query of queries) {
    if (exact.has(query)) {
      answer.push(query);
      continue;
    }
    const lower = query.toLowerCase();
    if (byLower.has(lower)) {
      answer.push(byLower.get(lower));
      continue;
    }
    const key = pattern(query);
    if (byPattern.has(key)) {
      answer.push(byPattern.get(key));
    } else {
      answer.push('');
    }
  }
  return answer;
}

