function spellchecker(wordlist, queries) {
  const isVowel = c => 'aeiou'.includes(c);
  const vowelMatch = (a, b) => {
    if (a.length !== b.length) return false;
    for (let i = 0; i < a.length; i++) {
      const x = a[i].toLowerCase(), y = b[i].toLowerCase();
      if (x === y) continue;
      if (isVowel(x) && isVowel(y)) continue;
      return false;
    }
    return true;
  };
  return queries.map(q => {
    for (const w of wordlist) if (w === q) return w;
    for (const w of wordlist) if (w.toLowerCase() === q.toLowerCase()) return w;
    for (const w of wordlist) if (vowelMatch(w, q)) return w;
    return '';
  });
}

