function generate(rand, size) {
  const large = size === 'large';
  const consonants = large ? 'bcdfghklmnprst' : 'kt';
  const vowels = large ? 'aeiou' : 'aei';
  const pick = s => s[Math.floor(rand() * s.length)];
  const caseFlip = c => (rand() < 0.3 ? c.toUpperCase() : c.toLowerCase());
  const maxLen = large ? 7 : 4;
  const makeWord = () => {
    const len = 1 + Math.floor(rand() * maxLen);
    let word = '';
    for (let i = 0; i < len; i++) word += caseFlip(rand() < 0.45 ? pick(vowels) : pick(consonants));
    return word;
  };
  const wordCount = large ? 2000 : 1 + Math.floor(rand() * 6);
  const queryCount = large ? 2000 : 1 + Math.floor(rand() * 8);
  const wordlist = [];
  for (let i = 0; i < wordCount; i++) {
    if (wordlist.length && rand() < 0.25) {
      const base = wordlist[Math.floor(rand() * wordlist.length)];
      wordlist.push([...base].map(c => ('aeiouAEIOU'.includes(c) && rand() < 0.5 ? caseFlip(pick(vowels)) : caseFlip(c))).join(''));
    } else wordlist.push(makeWord());
  }
  const queries = [];
  for (let i = 0; i < queryCount; i++) {
    const base = wordlist[Math.floor(rand() * wordlist.length)];
    const r = rand();
    if (r < 0.2) queries.push(base);
    else if (r < 0.45) queries.push([...base].map(caseFlip).join(''));
    else if (r < 0.75) queries.push([...base].map(c => ('aeiouAEIOU'.includes(c) ? caseFlip(pick(vowels)) : caseFlip(c))).join(''));
    else if (r < 0.85) queries.push([...base].map(c => (rand() < 0.3 ? caseFlip(pick(consonants)) : c)).join(''));
    else queries.push(makeWord());
  }
  return [wordlist, queries];
}
